new='''/**
 * A fly-by (27 F2, a summon on the fly): the node flies out to a live point and, without stopping there,
 * carries on to wherever its layout puts it now. It speeds up toward the point and slows only on arriving
 * home, so it is at its fastest as it passes: the call it gives there lands at that instant. Along the same
 * gentle arcs as a sortie, with a wake on the way out.
 * `jump`: a captain new to the scene (22 C8, K-13) is hidden until the call: it drops out of hyperspace at the
 * point instead of flying out, fully in as the out leg ends, then carries on.
 * `waitS` (E4's P4): when the captain's next sortie sets off soon, it eases to a stop a little way on from the point
 * (still short of home), waits there that long, and only then goes home; the sortie takes over from where it is drawn.
 */
export class Flyby implements Fx {
  readonly kind = 'travel';
  private t = 0;
  private readonly streak: Streak | null;
  private passed: [number, number] | null = null;
  private last: [number, number];
  constructor(
    private readonly scene: GraphScene, private readonly pk: string, private readonly start: [number, number],
    private readonly to: () => readonly [number, number] | null, private readonly look: () => readonly [number, number] | null,
    private readonly outS: number, private readonly onS: number, private readonly wake = 0,
    private readonly jump = false, private readonly waitS = 0,
  ) {
    scene.own(pk);
    scene.placeAt(pk, start[0], start[1]);
    this.last = [start[0], start[1]];
    this.streak = wake ? new Streak(scene.fxLayer(), TRAIL_COLOR) : null;
    if (jump) scene.fadeView(pk, 0);
  }
  private arc(a: readonly [number, number], b: readonly [number, number], k: number): [number, number] {
    const len = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1;
    const lift = len * 0.18;
    const cx = (a[0] + b[0]) / 2 + (-(b[1] - a[1]) / len) * lift;
    const cy = (a[1] + b[1]) / 2 + ((b[0] - a[0]) / len) * lift;
    const v = 1 - k;
    return [v * v * a[0] + 2 * v * k * cx + k * k * b[0], v * v * a[1] + 2 * v * k * cy + k * k * b[1]];
  }
  update(dt: number): boolean {
    this.t += dt;
    const t = this.t;
    let p: [number, number];
    if (t < this.outS) {
      const slot = this.to() ?? this.passed ?? this.start;
      const u = t / Math.max(1e-3, this.outS);
      if (this.jump) {
        // Hidden at the spot, then in over the last JUMP_IN_S of the out leg (never flying out).
        p = [slot[0], slot[1]];
        const w = Math.min(JUMP_IN_S, this.outS);
        this.scene.fadeView(this.pk, Math.max(0, Math.min(1, (t - (this.outS - w)) / Math.max(1e-3, w))));
        const look = this.look();
        if (look && Math.abs(look[0] - slot[0]) > 1e-6) this.scene.faceView(this.pk, look[0] - slot[0]);
      } else {
        p = this.arc(this.start, slot, u * u); // speeding up toward the point
        this.streak?.draw(this.start, p, this.wake / this.scene.currentScale(), 0.6 * (1 - u));
      }
    } else {
      const slot = (this.passed ??= [...(this.to() ?? this.start)] as [number, number]);
      if (this.jump) this.scene.fadeView(this.pk, 1);
      const home = this.scene.goalOf(this.pk) ?? this.start;
      const k = (t - this.outS) / Math.max(1e-3, this.onS);
      if (this.waitS > 0) {
        // On a little way and to a stop (its next sortie is soon), waiting, then home.
        const stop: [number, number] = [slot[0] + (home[0] - slot[0]) * WAIT_COAST, slot[1] + (home[1] - slot[1]) * WAIT_COAST];
        if (k < 1) p = this.arc(slot, stop, 1 - (1 - k) * (1 - k));
        else if (t < this.outS + this.onS + this.waitS) p = stop;
        else p = this.arc(stop, home, easeInOut(Math.min(1, (t - this.outS - this.onS - this.waitS) / Math.max(1e-3, this.onS))));
      } else {
        const u = Math.min(1, k);
        p = this.arc(slot, home, 1 - (1 - u) * (1 - u)); // slowing only as it gets there
      }
      this.streak?.draw(p, p, 0, 0);
    }
    // Nosed the way it is going now (the arcs can bend against the chord), so the facing follows the motion.
    const dx = p[0] - this.last[0];
    if (Math.abs(dx) > 1e-4) this.scene.faceView(this.pk, dx);
    this.last = p;
    this.scene.placeAt(this.pk, p[0], p[1]);
    return t < this.outS + this.onS + (this.waitS > 0 ? this.waitS + this.onS : 0);
  }
  destroy(): void {
    if (this.jump) this.scene.fadeView(this.pk, 1);
    this.scene.release(this.pk);
    this.scene.restoreFacing(this.pk);
    this.streak?.destroy();
  }
}

/** How far of the way on from the spot to home a waiting fly-by (`waitS`) coasts before it stops (a fraction). */
const WAIT_COAST = 0.35;

